exercises.solution:
def violations(ressources):
    messages = []
    for r in ressources:
        config = r.get("config", {})
        if r["type"] == "aws_s3_bucket" and config.get("public") is True:
            messages.append(f"{r['nom']} : compartiment public interdit")
        if "projet" not in config.get("tags", {}):
            messages.append(f"{r['nom']} : étiquette projet manquante")
    return messages

for m in violations(ressources):
    print(m)
